function crSetTransmission(t){
  CR.transmission = t;
  crSfx('gear');
  toast(t === 'manual' ? 'گیربکس دستی فعال شد (کلید E دنده بالا / Q دنده پایین)' : 'گیربکس اتوماتیک فعال شد', 'activity');
  crRenderApp();
}

