/* ================================================================
   پایان دور مسابقه و اهدای سکه
   ================================================================ */
function crEndRound(){
  CR.active = false;
  if(CR.raf) cancelAnimationFrame(CR.raf);
  if(CR.engineGain && CR.audioCtx){
    try{ CR.engineGain.gain.setValueAtTime(0.001, CR.audioCtx.currentTime); }catch(e){}
  }

  const p = CR.p;
  const tripKm = Math.round((p.tripMeters / 1000) * 10) / 10;
  crAddOdo(CR.carId, tripKm);

  const topSpd = Math.round(p.kmh);
  const oldBest = crGetBestSpeed();
  const isNewRecord = topSpd > oldBest;
  if(isNewRecord){ crSetBestSpeed(topSpd); }

  // پاداش سکه: ۵ تا ۲۰ سکه متناسب با مسافت و رکورد
  let rewardCoins = Math.min(25, Math.max(5, Math.floor(tripKm * 3) + (isNewRecord ? 15 : 0)));
  if(typeof coinAdd === 'function'){
    coinAdd(rewardCoins, 'پاداش رانندگی در شهر ('+faNum(tripKm)+' کیلومتر)');
  }

  const modal = document.getElementById('crRoundModal');
  if(modal){
    modal.style.display = 'flex';
    modal.innerHTML = '<div class="crm-box">'
      +'<span class="crm-badge">'+ic('award',14)+'پایان دور مسابقه</span>'
      +'<h3>نتایج رانندگی و رکوردها</h3>'
      +'<div class="crm-stats-grid">'
        +'<div class="csg-card"><span>مسافت این دور</span><b>'+faNum(tripKm)+' کیلومتر</b></div>'
        +'<div class="csg-card"><span>حداکثر سرعت</span><b>'+faNum(topSpd)+' KM/H</b></div>'
        +'<div class="csg-card highlight"><span>پاداش دریافتی</span><b>+'+faNum(rewardCoins)+' سکه</b></div>'
        +'<div class="csg-card"><span>کیلومتر جدید ماشین</span><b>'+faNum(crGetOdo(CR.carId).toFixed(1))+' KM</b></div>'
      +'</div>'
      +(isNewRecord ? '<div class="crm-new-record">'+ic('zap',13)+'رکورد جدید سرعت ثبت شد! تبریک!</div>' : '')
      +'<div class="crm-acts">'
        +'<button class="btn gold" onclick="crStartGame()">'+ic('play',14)+' رانندگی مجدد</button>'
        +'<button class="btn ghost" onclick="crSetView(\'select_car\')">'+ic('car',14)+' تعویض ماشین</button>'
        +'<button class="btn ghost" onclick="crExitToMenu()">'+ic('home',14)+' منوی اصلی</button>'
      +'</div>'
    +'</div>';
  }
}

